namespace RevLink.Mobile.Views;
public class EventsPage:RevPage {
 bool mine;
 public EventsPage():base("Eventos"){}
 protected override async Task Load(){Reset("EVENTOS","ENCONTROS AUTOMOTIVOS");Add(Ui.Button("+ CRIAR EVENTO",()=>Open(new EventForm())),Ui.Button(mine?"Mostrar todos":"Minhas inscrições",async()=>{mine=!mine;await Reload();},Ui.Surface,Ui.Accent));var events=await Api.Get<List<EventDto>>("/api/events");var list=events.Where(e=>!mine||e.Joined).OrderBy(e=>e.EndAt<DateTime.UtcNow).ThenBy(e=>e.StartAt).ToList();if(list.Count==0)Add(Ui.Text("Nenhum evento encontrado.",15,Ui.Muted));foreach(var e in list)Add(Ui.Card(Ui.Text(e.EndAt<DateTime.UtcNow?"ENCERRADO":e.StartAt.ToLocalTime().ToString("dd MMM · HH:mm").ToUpperInvariant(),13,Ui.Accent,true),Ui.Text(e.Title,22,Ui.White,true),Ui.Text(e.Location,15,Ui.Muted),Ui.Text($"{e.ParticipantCount} / {e.MaxParticipants?.ToString()??"∞"} participantes · {e.HostTag}",13),Ui.Button(e.IsHost?"Gerenciar":e.Joined?"Inscrito · Ver detalhes":"Ver encontro",()=>Open(new EventDetails(e.Id)))));}
}
public class EventDetails(int id):RevPage("Encontro") {
 protected override async Task Load(){var e=await Api.Get<EventDto>($"/api/events/{id}");Reset(e.Title,$"ANFITRIÃO: {e.HostTag}");Add(Ui.Card(Ui.Text(e.Description),Ui.Text("LOCAL",12,Ui.Accent,true),Ui.Text(e.Location),Ui.Text("INÍCIO / FIM",12,Ui.Accent,true),Ui.Text(e.StartAt.ToLocalTime().ToString("dd/MM/yyyy HH:mm")),Ui.Text(e.EndAt.ToLocalTime().ToString("dd/MM/yyyy HH:mm")),Ui.Text($"{e.ParticipantCount} / {e.MaxParticipants?.ToString()??"∞"} participantes")));
 if(e.IsHost)Add(Ui.Button("Editar evento",()=>Open(new EventForm(e))),Ui.Button("Excluir evento",async()=>{if(await Confirm("Excluir o evento e todas as inscrições?")){await Api.Write(HttpMethod.Delete,$"/api/events/{id}");await Navigation.PopAsync();}},Ui.Surface,Ui.Danger));else if(e.Joined)Add(Ui.Button("Cancelar inscrição",async()=>{await Api.Write(HttpMethod.Delete,$"/api/events/{id}/leave");await Reload();},Ui.Surface,Ui.Danger));else if(e.EndAt<=DateTime.UtcNow)Add(Ui.Text("Evento encerrado.",15,Ui.Muted));else if(e.MaxParticipants.HasValue&&e.ParticipantCount>=e.MaxParticipants)Add(Ui.Text("Evento lotado.",15,Ui.Danger));else Add(Ui.Button("PARTICIPAR",async()=>{await Api.Write(HttpMethod.Post,$"/api/events/{id}/join");await Reload();}));
 Add(Ui.Text("PARTICIPANTES",18,Ui.White,true));var members=await Api.Get<List<MemberDto>>($"/api/events/{id}/members");foreach(var m in members){var row=Ui.Stack(Ui.Text(m.DriverTag+(m.UserId==e.HostId?" · anfitrião":"")));if(e.IsHost&&m.UserId!=e.HostId)row.Children.Add(Ui.Button("Remover",async()=>{if(await Confirm($"Remover {m.DriverTag}?")){await Api.Write(HttpMethod.Delete,$"/api/events/{id}/members/{m.UserId}");await Reload();}},Ui.Surface,Ui.Danger));Add(Ui.Card(row));}}
}
public class EventForm:FormPage {
 public EventForm(EventDto? e=null):base(e==null?"Novo encontro":"Editar encontro"){
 var title=Ui.Entry("Título",e?.Title);var description=Ui.Editor("Descrição",e?.Description);var location=Ui.Entry("Local / endereço",e?.Location);var start=e?.StartAt.ToLocalTime()??DateTime.Now.AddHours(1);var end=e?.EndAt.ToLocalTime()??start.AddHours(2);var sd=new DatePicker{Date=start.Date,MinimumDate=new DateTime(2000,1,1)};var st=new TimePicker{Time=start.TimeOfDay};var ed=new DatePicker{Date=end.Date,MinimumDate=new DateTime(2000,1,1)};var et=new TimePicker{Time=end.TimeOfDay};var max=Ui.Entry("Deixe vazio para ilimitado",e?.MaxParticipants?.ToString(),Keyboard.Numeric);
 Add(title,description,location,Ui.Text("INÍCIO",13,Ui.Accent,true),sd,st,Ui.Text("TÉRMINO",13,Ui.Accent,true),ed,et,Ui.Text("LIMITE DE PARTICIPANTES (inclui anfitrião)",13,Ui.Muted),max,Ui.Button("SALVAR EVENTO",async()=>{int? limit=null;if(!string.IsNullOrWhiteSpace(max.Text)){if(!int.TryParse(max.Text,out int n)||n<1)throw new Exception("Limite inválido.");limit=n;}DateTime? sdate=sd.Date,edate=ed.Date;TimeSpan? stime=st.Time,etime=et.Time;if(sdate==null||edate==null||stime==null||etime==null)throw new Exception("Selecione datas e horários.");var startAt=new DateTimeOffset(DateTime.SpecifyKind(sdate.Value.Date+stime.Value,DateTimeKind.Local));var endAt=new DateTimeOffset(DateTime.SpecifyKind(edate.Value.Date+etime.Value,DateTimeKind.Local));await Api.Write(e==null?HttpMethod.Post:HttpMethod.Put,e==null?"/api/events":$"/api/events/{e.Id}",new{title=Ui.Value(title),description=Ui.Value(description),location=Ui.Value(location),startAt,endAt,maxParticipants=limit});await Finish();}));}
}
